ALTER TABLE guild_events ADD COLUMN SpendEffectId TEXT NULL CHECK(SpendEffectId IS NULL OR (typeof(SpendEffectId)='text' AND SpendEffectId=upper(SpendEffectId) AND length(SpendEffectId)=36 AND substr(SpendEffectId,9,1)='-' AND substr(SpendEffectId,14,1)='-' AND substr(SpendEffectId,19,1)='-' AND substr(SpendEffectId,24,1)='-' AND length(replace(SpendEffectId,'-',''))=32 AND replace(SpendEffectId,'-','') NOT GLOB '*[^0-9A-F]*' AND SpendEffectId<>'00000000-0000-0000-0000-000000000000'));
